# Flashfreeze: "Counter target red or green spell."
# Cancel's COUNTER_SPELL (STACK_KIND_EQ SPELL on the stack) with the colour test "red or green"
# as an FOr of COLOR_HAS (MAPPER_GUIDE "Colours": never COLOR_IN, a subset test; B-54).
abilities = [
    SpellAbility(
        kind=SpellKind.INSTANT,
        effect=A(Verb.COUNTER_SPELL, {
            'target': Selector(
                count=QConst(value=1),
                mode=SelectorMode.TARGET,
                filter=FAnd(children=(
                    FAtom(pred=FAtomPred.STACK_KIND_EQ, string_value='SPELL'),
                    FOr(children=(
                        FAtom(pred=FAtomPred.COLOR_HAS, color='R'),
                        FAtom(pred=FAtomPred.COLOR_HAS, color='G'),
                    )),
                )),
                zones=(Zone(kind=ZoneKind.STACK, controller=ControllerRef.ANY),),
            ),
        }),
    ),
]
